selected = []
for item in sorted(root.rglob("*")):
    if not item.is_file():
        continue
    rel = item.relative_to(root)
    if any(part in {"node_modules", ".git", ".agents", ".codex", "__pycache__", "release"} for part in rel.parts):
        continue
    if item.name.startswith(".env") or item.suffix in {".log", ".pyc"}:
        continue
    if (len(rel.parts) == 1 and item.name in top_files) or rel.parts[0] in top_dirs or (rel.parts[0] == "artifacts" and item.name in evidence):
        selected.append(item)
with zipfile.ZipFile(archive, "w", compression=zipfile.ZIP_DEFLATED) as z:
    for item in selected:
        z.write(item, "figcheck/" + item.relative_to(root).as_posix())
with zipfile.ZipFile(archive) as z:
    assert z.testzip() is None
    names = z.namelist()
    for required in ["packages/ui/brand/mark.svg", "packages/ui/brand/generated/icon-512.png", "apps/chrome-extension/dist/icons/icon-16.png", "apps/chrome-extension/dist/icons/icon-32.png", "apps/chrome-extension/dist/icons/icon-48.png", "apps/chrome-extension/dist/icons/icon-128.png", "apps/figma-plugin/dist/manifest.json", "apps/figma-plugin/dist/code.js", "apps/figma-plugin/dist/ui.html", "apps/chrome-extension/dist/manifest.json", "apps/chrome-extension/dist/panel.js", "docs/설치-사용.md", "fixtures/sample.json"]:
        assert "figcheck/" + required in names, required
digest = hashlib.sha256(archive.read_bytes()).hexdigest()
(release / "FigCheck-MVP-0.3.23.sha256.txt").write_text(digest + "  " + archive.name + "\n", encoding="utf-8")
print(json.dumps({"path": str(archive), "bytes": archive.stat().st_size, "files": len(selected), "sha256": digest}, ensure_ascii=False))
